package com.bank.incident;

import java.util.List;
import java.util.logging.Logger;

public class IncidentResponseEngine {
    private static final Logger log = Logger.getLogger(IncidentResponseEngine.class.getName());
    private final List<IncidentMitigator> mitigators;

    public IncidentResponseEngine(List<IncidentMitigator> mitigators) {
        this.mitigators = mitigators;
    }

    public MitigationResult respond(Incident incident) {
        log.warning(() -> "INCIDENT: " + incident.getType() + " — " + incident.getDetail());
        for (IncidentMitigator m : mitigators) {
            if (m.handles(incident.getType())) {
                MitigationResult r = m.mitigate(incident);
                log.info(() -> "  MITIGATE NOW: " + r.getImmediateAction());
                log.info(() -> "  LONG-TERM FIX: " + r.getLongTermFix());
                return r;
            }
        }
        throw new IllegalStateException("No mitigator for " + incident.getType());
    }
}
