package com.bank.incident;

import java.util.List;
import java.util.logging.*;

public class IncidentResponseDemo {
    private static final Logger log = Logger.getLogger(IncidentResponseDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        IncidentResponseEngine engine = new IncidentResponseEngine(List.of(
            new Ec2HealthMitigator(), new RdsStorageMitigator(), new DeploymentMitigator()));

        engine.respond(new Incident(Incident.Type.EC2_HEALTH,
            "6/8 banking-api instances failing ALB health checks"));
        engine.respond(new Incident(Incident.Type.RDS_STORAGE,
            "bankingdb RDS FreeStorageSpace at 3% — transactions failing to write"));
        engine.respond(new Incident(Incident.Type.DEPLOYMENT,
            "v4.2 transfer-service deploy spiking 5xx for Rajesh/Priya transfers"));
    }
}
